4	 * Derives an owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over
5	 * the digits contained in the owner's {@code customerCode}.
6	 *
7	 * <p>The digits are processed right-to-left, doubling every second digit starting with
8	 * the rightmost (subtracting 9 when a doubled digit exceeds 9); the check digit is the
9	 * amount needed to bring the running total to the next multiple of ten. Non-digit
10	 * characters in the customer code are ignored. Null when the owner has no customer code.
11	 */
12	public final class CheckDigit {
13	
14	    private CheckDigit() {
15	    }
16	
17	    /** The Luhn check digit for the given owner, or null when it has no customer code. */
18	    public static Integer of(Owner owner) {
19	        String customerCode = owner.getCustomerCode();
20	        if (customerCode == null) {
21	            return null;
22	        }
23	        int sum = 0;
24	        boolean dbl = true;
25	        for (int i = customerCode.length() - 1; i >= 0; i--) {
26	            char c = customerCode.charAt(i);
27	            if (c < '0' || c > '9') {
28	                continue;
29	            }
30	            int d = c - '0';
31	            if (dbl) {
32	                d *= 2;
33	                if (d > 9) {
34	                    d -= 9;
35	                }
36	            }
37	            sum += d;
38	            dbl = !dbl;
39	        }
40	        return (10 - (sum % 10)) % 10;
41	    }
42	}
